mapper.select:
SELECT REQUEST_STATUS
FROM QUERY_REQUEST
WHERE REQUEST_ID = #{requestId}
  AND DRAFTER_ID = #{drafterId}
FOR UPDATE

mapper.update:
UPDATE QUERY_REQUEST
SET TITLE = #{title},
    PURPOSE = #{purpose, jdbcType=CLOB}
WHERE REQUEST_ID = #{requestId}
  AND DRAFTER_ID = #{drafterId}
  AND REQUEST_STATUS = 'DRAFT'

mapper.delete:
DELETE FROM QUERY_ITEM
WHERE REQUEST_ID = #{requestId}
  AND EXISTS (
      SELECT 1
      FROM QUERY_REQUEST R
      WHERE R.REQUEST_ID = #{requestId}
        AND R.DRAFTER_ID = #{drafterId}
        AND R.REQUEST_STATUS = 'DRAFT'
  )

DELETE FROM QUERY_REQUEST
WHERE REQUEST_ID = #{requestId}
  AND DRAFTER_ID = #{drafterId}
  AND REQUEST_STATUS = 'DRAFT'
